<div class="table-responsive"><table class="table"><thead><tr><th>O.S.</th><th>Funcionário</th><th>Intervalo</th><th>Horas</th><th>Serviço</th><th>Controle PCM</th><th>Ação</th></tr></thead><tbody>
<?php foreach ($rows as $entry): $snap = json_decode($entry->snapshot, true); ?>
<tr class="<?= $entry->controle_pcm==='lancado'?'pcm-tratado':'' ?>"><td><?= h($snap['os_numero']) ?> / <?= h($snap['os_filial']) ?><small class="d-block"><?= h($snap['setor_nome']) ?> · <?= h($snap['caderno_nome']) ?></small></td><td><?= h($entry->funcionario_nome) ?><small class="d-block"><?= h($entry->funcionario_matricula) ?> / <?= h($entry->funcionario_filial) ?></small></td><td><?= h($entry->inicio->setTimezone('America/Sao_Paulo')->format('d/m/Y H:i')) ?><br><?= h($entry->fim->setTimezone('America/Sao_Paulo')->format('d/m/Y H:i')) ?></td><td><?= number_format($entry->minutos / 60, 2, ',', '.') ?></td><td class="text-break"><?= h($entry->descricao) ?></td><td><?= $entry->cancelado ? 'Cancelado' : h(['pendente' => 'Pendente de lançamento no TOTVS', 'conferido' => 'Conferido pelo PCM', 'lancado' => 'Lançado manualmente no TOTVS'][$entry->controle_pcm]) ?></td><td><?= $this->Html->link('Detalhes', ['controller' => 'Apontamentos', 'action' => 'view', $entry->id]) ?></td></tr>
<?php endforeach; ?>
<?php if (count($rows) === 0): ?><tr><td colspan="7">Nenhum apontamento encontrado.</td></tr><?php endif; ?></tbody></table></div>
